def control(obs):
    dt = obs.get('dt', 0.1)
    hitch_deg = obs.get('hitch_deg', 0.0)
    progress = obs.get('progress', {})
    covered = progress.get('covered', 0.0)
    status = obs.get('status', '')

    # Handle pinned/jackknife state or active unpin recovery
    if status in ['PINNED', 'JACKKNIFED']:
        state['unpinning'] = True
        state['unpin_start_covered'] = covered

    if state['unpinning']:
        dist_pulled = abs(covered - state['unpin_start_covered'])
        # Note warning: keep steering very gentle when unpinning forward
        if dist_pulled < 2.0 and abs(hitch_deg) > 5.0:
            return {
                'steer_deg': -0.15 * hitch_deg,
                'speed_mps': 0.6,
                'look_deg': 0.0
            }
        else:
            state['unpinning'] = False

    # Scan barriers
    views = obs.get('views', {})
    left_dist = 999.0
    right_dist = 999.0
    for vname, vdata in views.items():
        origin = vdata.get('origin', [0, 0])
        walls = vdata.get('walls', [])
        for b_deg, d_m in walls:
            b_rad = math.radians(b_deg)
            px = origin[0] + d_m * math.cos(b_rad)
            py = origin[1] + d_m * math.sin(b_rad)
            if -7.5 <= px <= 1.5:
                if py > 0 and py < left_dist:
                    left_dist = py
                elif py < 0 and (-py) < right_dist:
                    right_dist = -py

    # Baseline S-bend hitch profile
    if covered < 6.0:
        target_hitch = 0.0
    elif covered < 18.0:
        target_hitch = 12.0
    elif covered < 28.0:
        target_hitch = -10.0
    elif covered < 36.0:
        target_hitch = 0.0
    else:
        target_hitch = 0.0

    # Reactive adjustments
    if right_dist < 1.7:
        target_hitch += (1.7 - right_dist) * 12.0
    if left_dist < 1.7:
        target_hitch -= (1.7 - left_dist) * 12.0

    target_hitch = max(-25.0, min(25.0, target_hitch))

    # PD control on hitch angle
    hitch_err = hitch_deg - target_hitch
    d_err = (hitch_err - state['last_hitch_err']) / max(dt, 0.01)
    state['last_hitch_err'] = hitch_err

    Kp = 2.5
    Kd = 0.4
    steer = Kp * hitch_err + Kd * d_err
    steer = max(-40.0, min(40.0, steer))

    # Alternate looking between left and right mirror
    t_sec = obs.get('t', 0.0)
    look = -64.0 if (int(t_sec // 2) % 2 == 0) else 64.0

    return {
        'steer_deg': steer,
        'speed_mps': -0.45,
        'look_deg': look
    }
